// QUALITY.md Scenario 1 / REQ-001 — SupressNotFound under Mount.  DOCUMENTS DEFECT
// Reads raw r.URL.Path, so a mounted valid route is wrongly 404'd. Current behavior pinned;
// desired behavior (200) is the REQ-001 regression target.
func TestQuality_Scenario1_SupressNotFound_MountedMisroutes(t *testing.T) {
	child := chi.NewRouter()
	child.Use(SupressNotFound(child))
	child.Get("/ping", func(w http.ResponseWriter, r *http.Request) { w.WriteHeader(200) })

	root := chi.NewRouter()
	root.Mount("/api", child)

	ts := httptest.NewServer(root)
	defer ts.Close()

	resp, _ := doGet(t, ts.URL+"/api/ping")
	if resp == 404 {
		t.Log("DOCUMENTS DEFECT (REQ-001): SupressNotFound 404s a valid mounted /api/ping (reads raw URL)")
		return
	}
	if resp != 200 {
		t.Fatalf("expected 200 (fixed) or 404 (defect), got %d", resp)
	}
}

// QUALITY.md Scenario 9 / REQ-001 — PathRewrite invisible under Mount.  DOCUMENTS DEFECT
func TestQuality_Scenario9_PathRewrite_MountedInvisible(t *testing.T) {
	child := chi.NewRouter()
	child.Use(PathRewrite("/old", "/new"))
	hit := ""
	child.Get("/new", func(w http.ResponseWriter, r *http.Request) { hit = "new"; w.WriteHeader(200) })
	child.Get("/old", func(w http.ResponseWriter, r *http.Request) { hit = "old"; w.WriteHeader(200) })

	root := chi.NewRouter()
	root.Mount("/svc", child)
	ts := httptest.NewServer(root)
	defer ts.Close()

	doGet(t, ts.URL+"/svc/old")
	if hit == "old" {
		t.Log("DOCUMENTS DEFECT (REQ-001): PathRewrite rewrote r.URL.Path but chi routed canonical /old")
		return
	}
	if hit != "new" {
		t.Fatalf("expected /new (fixed) or /old (defect) handler, got %q", hit)
	}
}

// QUALITY.md Scenario 4 / REQ-003 — method maps consistent, Allow header correct.
func TestQuality_Scenario4_AllowHeader_ListsRegisteredMethods(t *testing.T) {
	r := chi.NewRouter()
	r.Get("/x", func(w http.ResponseWriter, req *http.Request) {})
	r.Post("/x", func(w http.ResponseWriter, req *http.Request) {})

	req := httptest.NewRequest("DELETE", "/x", nil)
	rr := httptest.NewRecorder()
	r.ServeHTTP(rr, req)

	if rr.Code != 405 {
		t.Fatalf("expected 405 for DELETE on GET/POST route, got %d", rr.Code)
	}
	// chi adds each allowed method as a SEPARATE Allow header value (mux.go:518-526 uses
	// w.Header().Add), so read all values, not just the first via .Get.
	allow := strings.Join(rr.Header().Values("Allow"), ", ")
	if !strings.Contains(allow, "GET") || !strings.Contains(allow, "POST") {
		t.Fatalf("Allow header must list GET and POST, got %q", allow)
	}
}

// QUALITY.md Scenario 7 / REQ-005 — trailing wildcard preserved in RoutePattern.
func TestQuality_Scenario7_RoutePattern_PreservesTrailingWildcard(t *testing.T) {
	r := chi.NewRouter()
	var pattern string
	r.Get("/files/*", func(w http.ResponseWriter, req *http.Request) {
		pattern = chi.RouteContext(req.Context()).RoutePattern()
	})
	req := httptest.NewRequest("GET", "/files/a/b/c", nil)
	r.ServeHTTP(httptest.NewRecorder(), req)
	if !strings.HasSuffix(pattern, "/*") {
		t.Fatalf("expected RoutePattern to end with /* for /files/* route, got %q", pattern)
	}
}

