// [Req: inferred — REQ-001 / C-STR-1] reference cohort: StripSlashes uses RoutePath under Mount.
func TestQuality_StripSlashes_UsesRoutePathUnderMount(t *testing.T) {
	child := chi.NewRouter()
	child.Use(StripSlashes)
	ok := false
	child.Get("/ping", func(w http.ResponseWriter, r *http.Request) { ok = true; w.WriteHeader(200) })

	root := chi.NewRouter()
	root.Mount("/api", child)
	ts := httptest.NewServer(root)
	defer ts.Close()

	// trailing slash should be stripped via canonical RoutePath and still route under mount
	code, _ := doGet(t, ts.URL+"/api/ping/")
	if !ok || code != 200 {
		t.Fatalf("StripSlashes (reference cohort) must route /api/ping/ to /ping under mount; code=%d ok=%v", code, ok)
	}
}

// [Req: inferred — REQ-001 / C-URF-1] reference cohort: URLFormat updates RoutePath under Mount.
