// [Req: inferred — REQ-007 / C-CMP-5,6] no Content-Encoding when content type is not compressible.
func TestQuality_Compress_NoEncodingForNonCompressibleType(t *testing.T) {
	r := chi.NewRouter()
	r.Use(Compress(5, "text/html"))
	r.Get("/bin", func(w http.ResponseWriter, req *http.Request) {
		w.Header().Set("Content-Type", "application/octet-stream")
		w.WriteHeader(200)
		w.Write([]byte("rawbytes"))
	})
	ts := httptest.NewServer(r)
	defer ts.Close()

	req, _ := http.NewRequest("GET", ts.URL+"/bin", nil)
	req.Header.Set("Accept-Encoding", "gzip")
	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		t.Fatalf("request failed: %v", err)
	}
	defer resp.Body.Close()
	if ce := resp.Header.Get("Content-Encoding"); ce != "" {
		t.Fatalf("non-compressible content type must not get Content-Encoding, got %q", ce)
	}
}

