// [Req: inferred — REQ-003] AllowContentType whitelist rejects an unlisted type with 415.
func TestQuality_AllowContentType_RejectsUnlisted(t *testing.T) {
	r := chi.NewRouter()
	r.Use(AllowContentType("application/json"))
	r.Post("/x", func(w http.ResponseWriter, req *http.Request) { w.WriteHeader(200) })

	req := httptest.NewRequest("POST", "/x", strings.NewReader("{}"))
	req.Header.Set("Content-Type", "text/xml")
	rr := httptest.NewRecorder()
	r.ServeHTTP(rr, req)
	if rr.Code != http.StatusUnsupportedMediaType {
		t.Fatalf("expected 415 for unlisted content type, got %d", rr.Code)
	}
}

